create or replace function public.admin_set_user_access(p_target_user_id uuid, p_is_admin boolean default false, p_role text default 'customer', p_subscription_tier text default 'free', p_is_business_user boolean default false, p_reason text default 'Admin access change') returns jsonb language plpgsql security definer set search_path=public,auth,pg_temp as $function$ declare old jsonb; result jsonb; normalized_tier text:=lower(trim(coalesce(p_subscription_tier,'free'))); begin if not exists(select 1 from public.profiles where id=auth.uid() and (is_admin=true or lower(coalesce(role::text,'')) in ('admin','owner','platform_admin','super_admin'))) then raise exception 'admin authorization required'; end if; if p_target_user_id is null then raise exception 'target user required'; end if; if lower(coalesce(p_role,'')) not in ('customer','business_owner','admin','owner','platform_admin','super_admin') then raise exception 'invalid role'; end if; if normalized_tier='standard' or normalized_tier='growth' then normalized_tier:='premium'; end if; if normalized_tier not in ('free','premium','family','fleet','enterprise') then raise exception 'invalid subscription tier: %',normalized_tier; end if; select to_jsonb(p) into old from public.profiles p where p.id=p_target_user_id for update; if old is null then raise exception 'profile not found'; end if; update public.profiles set is_admin=p_is_admin,is_business_user=p_is_business_user,role=p_role,subscription_tier=normalized_tier::subscription_tier,updated_at=now() where id=p_target_user_id returning to_jsonb(profiles.*) into result; insert into public.admin_capability_audit(admin_user_id,target_user_id,previous_state,new_state,reason) values(auth.uid(),p_target_user_id,old,result,coalesce(nullif(trim(p_reason),''),'Admin access change')); return result; end $function$;
